self.KB_CONTENT["card:777301"]={"id":"card:777301","ty":"card","sourceId":"777301","title":"『退料單建立作業』中的『.簽核狀態 (TC016)』為何？","ver":"GP4以上","topic":"狀態","keywords":["狀態","電子","料單","簽核"],"y":"other","answer":"* 此欄位僅作顯示。簽核狀態類型區分為0.待處理、1.簽核中、2.退件、3.已核准、4.取消確認中、5.作廢中、6.取消作廢中及N.不執行電子簽核。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
