self.KB_CONTENT["field:753354"]={"id":"field:753354","ty":"field","sourceId":"753354","title":"生產線代號","ver":"iGP","topic":"","keywords":[],"job":"產能資料建立作業","code":"MY001","answer":"* 不可空白。* 可按[F2]生產線資料查詢。預設：人工產能=每日人工產能機器產能=每日機器產能有效人時=每日人工產能×標準人工效率有效機時=每日機器產能×標準機器負荷","file":"fields.jsonl"};
