self.KB_CONTENT["field:843361"]={"id":"field:843361","ty":"field","sourceId":"843361","title":"箱數","ver":"iGP 1.0.14以上","topic":"","keywords":[],"job":"單箱包裝數量","code":"","answer":"【箱數】是由【截止箱數】-【起始箱數】+1計算而來，若要由系統運算，可先於『品號資料建立作業』中設定【標準包裝】的【外包裝商品數】，於『PACKING LIST建立作業』，單身帶出資料時即會自動換算【箱數】。","file":"fields.jsonl"};
