self.KB_CONTENT["field:802065"]={"id":"field:802065","ty":"field","sourceId":"802065","title":"申請人","ver":"GP40;IGP","topic":"","keywords":[],"job":"費用申請單建立作業","code":"","answer":"費用申請單【申請人】取『員工姓名建立作業』中的在職員工。若人員離職，請於基本資料管理系統->『員工姓名建立作業 』將該員工【離職日】補入，後續費用申請單的申請人開窗就不會看到離職員工。","file":"fields.jsonl"};
